struct TissueState {
    central: f64,
    tissue: f64
}

fn step(s: TissueState, dt: f64) -> TissueState {
    let to_tissue = 0.12 * s.central
    let to_central = 0.06 * s.tissue
    let cleared = 0.04 * s.central
    TissueState {
        central: s.central - dt * to_tissue + dt * to_central - dt * cleared,
        tissue: s.tissue + dt * to_tissue - dt * to_central
    }
}

fn total_mass(s: TissueState) -> f64 {
    s.central + s.tissue
}

