    var s = TissueState { central: 45.00, tissue: 0.0 }
    let start_mass = total_mass(s)
    let dt = 0.03
    var i = 0
    while i < 19 {
        s = step(s, dt)
        i = i + 1
    }
    if s.central <= 0.0 { return 1 }
    if s.tissue <= 0.0 { return 2 }
    if total_mass(s) >= start_mass { return 3 }
    return 0
}

