struct Oct {
    e: [f64; 8]
}

fn basis(idx: i64) -> Oct with Mut {
    var v: [f64; 8] = [0.0; 8]
    v[idx as usize] = 1.0
    Oct { e: v }
}

fn add(a: Oct, b: Oct) -> Oct with Mut {
    var v: [f64; 8] = [0.0; 8]
    var i: i64 = 0
    while i < 8 {
        v[i as usize] = a.e[i as usize] + b.e[i as usize]
        i = i + 1
    }
    Oct { e: v }
}

fn norm_sq(o: Oct) -> f64 with Mut {
    var total = 0.0
    var i: i64 = 0
    while i < 8 {
        total = total + o.e[i as usize] * o.e[i as usize]
        i = i + 1
    }
    total
}

fn main() -> i32 with IO, Mut, Div, Panic, NonAssoc {
    let a = basis(6)
    let b = basis(4)
    let c = add(a, b)
    let n = norm_sq(c)
    assert(n > 0.99)
    assert(n < 2.01)
    return 0
}

