    while i < 8 {
        var j: i64 = 0
        while j < 8 {
            let s = sigma(i, j)
            var tgt: i64 = 0
            if i == 0 { tgt = j }
            else if j == 0 { tgt = i }
            else { tgt = xor3(i, j) }
            var sf: f64 = 1.0
            if s < 0 { sf = 0.0 - 1.0 }
            let v = sf * OA[i]
            let w = v * OB[j]
            OC[tgt] = OC[tgt] + w
            j = j + 1
        }
        i = i + 1
    }
}

