    set_oa_basis(ai)
    set_ob_basis(bi)
    oct_mul_global()
    // OC = ea*eb. Copy to OA for next multiply.
    var k: i64 = 0
    while k < 8 { OA[k] = OC[k]; k = k + 1 }
    set_ob_basis(ci)
